#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> X(N);
    int H = 0;
    for (int &x : X) {
        cin >> x;
        H = max(H, x);
    }

    for (int level = H; level >= 1; --level) {
        for (int i = 0; i < N; ++i) {
            if (i > 0) cout << ' ';
            cout << (X[i] >= level ? 1 : 0);
        }
        cout << '\n';
    }

    return 0;
}
